1	export interface Scenario {
2	  customer: { yearsWithMHPCO: number };
3	  steps: Step[];
4	}
5	
6	export interface QuoteStep {
7	  op: "quote";
8	  items: { type: string; material?: string; enchantment?: number; cursed?: boolean }[];
9	}
10	
11	export type Step = QuoteStep;
12	
13	export interface ScenarioResults {
14	  results: ({ premium: number } | { payout: number; remainingCap: number })[];
15	}
16	
17	const PROCESSING_FEE = 5;
18	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
19	  sword: 100,
20	  amulet: 60,
21	  staff: 80,
22	  potion: 40,
23	};
24	const FIRST_INSURANCE_SURCHARGE = 0.1;
25	
26	// Percentage arithmetic leaves values like 71.00000000000001, which would
27	// otherwise round up to 72. Settle the float noise before rounding.
28	const FLOAT_NOISE_DIGITS = 6;
29	const withoutFloatNoise = (amount: number): number =>
30	  Number(amount.toFixed(FLOAT_NOISE_DIGITS));
31	
32	const roundUpInFavourOfMHPCO = (amount: number): number =>
33	  Math.ceil(withoutFloatNoise(amount));
34	
35	type Item = QuoteStep["items"][number];
36	
37	const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
38	
39	const quotePremium = (step: QuoteStep): number => {
40	  const policyBasePremium = step.items.reduce(
41	    (sum, item) => sum + basePremiumOf(item),
42	    0,
43	  );
44	  return roundUpInFavourOfMHPCO(
45	    policyBasePremium * (1 + FIRST_INSURANCE_SURCHARGE) + PROCESSING_FEE,
46	  );
47	};
48	
49	export const runScenario = (scenario: Scenario): ScenarioResults => ({
50	  results: scenario.steps.map((step) => ({ premium: quotePremium(step) })),
51	});
