const increasedBy = (amount: number, rate: number): number =>
  amount * (1 + rate);

const quotePremium = (step: QuoteStep): number => {
  const policyBasePremium = step.items.reduce(
    (sum, item) => sum + basePremiumOf(item),
    0,
  );
  return roundUpInFavourOfMHPCO(
    increasedBy(policyBasePremium, FIRST_INSURANCE_SURCHARGE) + PROCESSING_FEE,
  );
};
